const abbrTip = word => abbrInfo[word] || (statInfo.some(([s])=>s === (statAliases[word] || word)) ? `${word} — ${statTitle(word)}` : '');
// Сокращения в тексте страницы сами получают подсказку: <abbr class="has-tip" data-tip>. Новое содержимое
// (перерисовка вкладок, карточки) размечается наблюдателем. Поля ввода, кнопки и элементы со своей подсказкой не трогаем.
(()=>{
  if(typeof document === 'undefined' || typeof MutationObserver === 'undefined') return;
  const words = [...Object.keys(abbrInfo), ...statInfo.map(([s])=>s), ...Object.keys(statAliases)];
  const pattern = new RegExp(`(?<![А-Яа-яЁёA-Za-z0-9])(${words.sort((a, b)=>b.length - a.length).join('|')})(?![А-Яа-яЁёA-Za-z0-9])`, 'g');
  const skip = 'script, style, textarea, select, option, input, button, abbr, [data-tip], [title], [contenteditable], .tip-box';
  const mark = root => {
    const start = root.nodeType === 3 ? root.parentElement : root;
    if(!start || start.closest(skip)) return;
    const nodes = [];
    if(root.nodeType === 3) nodes.push(root);
    else {
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode: node => !node.parentElement.closest(skip) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT
      });
      while(walker.nextNode()) nodes.push(walker.currentNode);
    }
    nodes.forEach(node=>{
      const text = node.nodeValue;
      pattern.lastIndex = 0;
      if(!pattern.test(text)) return;
      pattern.lastIndex = 0;
      const frag = document.createDocumentFragment();
      let pos = 0, m;
      while((m = pattern.exec(text))){
        const tip = abbrTip(m[1]);
        if(!tip) continue;
        if(m.index > pos) frag.append(text.slice(pos, m.index));
        const abbr = document.createElement('abbr');
        abbr.className = 'has-tip';
        abbr.dataset.tip = tip;
        abbr.textContent = m[1];
        frag.append(abbr);
        pos = m.index + m[1].length;
      }
      if(!pos) return;
      if(pos < text.length) frag.append(text.slice(pos));
      node.parentNode.replaceChild(frag, node);
    });
  };
  const start = () => {
    mark(document.body);
    new MutationObserver(records=>records.forEach(r=>r.addedNodes.forEach(node=>{
      if(node.isConnected && (node.nodeType === 1 || node.nodeType === 3)) mark(node);
    }))).observe(document.body, {childList:true, subtree:true});
  };
  if(document.body) start(); else document.addEventListener('DOMContentLoaded', start);
})();
// Одна плашка на страницу: появляется у элемента с data-tip при наведении или фокусе, не вылезает за экран.
(()=>{
  if(typeof document === 'undefined') return;
  let box = null, timer = 0, current = null;
  const escTip = text => String(text).replace(/[&<>"]/g, ch=>({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;'}[ch]));
  const hide = () => { clearTimeout(timer); current = null; if(box) box.hidden = true; };
  const show = el => {
    const [head, ...rest] = el.dataset.tip.split('\n');
    if(!box){ box = document.createElement('div'); box.className = 'tip-box'; box.setAttribute('role', 'tooltip'); document.body.append(box); }
    box.innerHTML = `<b class="tip-head">${escTip(head)}</b>${rest.map(line=>{
      const level = line.match(/^(\d+) — (.*)$/);
      return level ? `<p class="tip-level"><span>${level[1]}</span>${escTip(level[2])}</p>` : `<p>${escTip(line)}</p>`;
    }).join('')}`;
    box.hidden = false;
    const r = el.getBoundingClientRect(), w = box.offsetWidth, h = box.offsetHeight;
    const left = Math.max(8, Math.min(r.left, innerWidth - w - 8));
    const top = r.bottom + 6 + h <= innerHeight ? r.bottom + 6 : Math.max(8, r.top - h - 6);
    box.style.left = `${left + scrollX}px`;
    box.style.top = `${top + scrollY}px`;
  };
  const enter = ev => {
    const el = ev.target.closest?.('[data-tip]');
    if(!el || el === current || !el.dataset.tip) return;
    current = el;
    clearTimeout(timer);
    timer = setTimeout(()=>show(el), ev.type === 'focusin' ? 0 : 250);
  };
  const leave = ev => {
    if(current && !current.contains(ev.relatedTarget)) hide();
  };
  document.addEventListener('mouseover', enter);
  document.addEventListener('mouseout', leave);
  document.addEventListener('focusin', enter);
  document.addEventListener('focusout', leave);
  addEventListener('scroll', hide, true);
  document.addEventListener('keydown', ev=>{ if(ev.key === 'Escape') hide(); });
})();

// Подсветка найденного: оборачивает совпадения в <mark class="search-hit"> внутри root,
// а поля ввода с совпадением помечает классом search-hit-field. Регистр и ё/е не важны.
const searchFold = text => String(text).toLowerCase().replace(/ё/g, 'е');
function highlightSearch(root, query){
  if(!root) return;
  root.querySelectorAll('mark.search-hit').forEach(mark=>{
    const parent = mark.parentNode;
    parent.replaceChild(document.createTextNode(mark.textContent), mark);
    parent.normalize();
  });
  root.querySelectorAll('.search-hit-field').forEach(el=>el.classList.remove('search-hit-field'));
  const q = searchFold(query).trim();
  if(!q) return;
  root.querySelectorAll('input:not([type=checkbox]):not([type=radio]):not([type=hidden]), textarea').forEach(el=>{
    if(el.value && searchFold(el.value).includes(q)) el.classList.add('search-hit-field');
  });
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: node => node.nodeValue.trim() && !node.parentElement.closest('script, style, textarea, select, option, button')
      ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT
  });
  const nodes = [];
  while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node=>{
    const text = node.nodeValue, folded = searchFold(text);
    if(folded.length !== text.length || !folded.includes(q)) return;
    const frag = document.createDocumentFragment();
    let pos = 0, at;
    while((at = folded.indexOf(q, pos)) !== -1){
      if(at > pos) frag.append(text.slice(pos, at));
      const mark = document.createElement('mark');
      mark.className = 'search-hit';
      mark.textContent = text.slice(at, at + q.length);
      frag.append(mark);
      pos = at + q.length;
    }
    if(pos < text.length) frag.append(text.slice(pos));
    node.parentNode.replaceChild(frag, node);
  });
}
